    "description": "上交所科创芯片ETF即将通过沪港ETF互挂实现出海。据悉，跟踪该ETF的港交所互挂基金已于10月28日获批，预计将于11月6日在香港联交所上市，境外投资者可在香港市场直接交易，便捷配置科创板芯片产业链资产。据介绍，该ETF跟踪上证科创板芯片指数，样本覆盖半导体材料与设备、芯片设计、晶圆制造、封装测试等全产业链环节，集中反映科创板集成电路企业的整体表现。截至10月28日，境内市场共有11只ETF跟踪该指数，合计规模574亿元。（中证报）",
