    "content": "中新网重庆10月29日电 (马佳欣)29日，重庆国际人才交流大会·第四届重庆三峡人才节新闻发布会在重庆万州举行。重庆市万州区委常委、组织部部长彭锋表示，重庆三峡人才节已连续举办三届，推动渝东北10区县落地人才项目122个、实现成果转化292项，重庆三峡人才节已成为渝东北区域招才引智的“金字招牌”。"
