    "title": "通讯丨“吉祥方舟”情暖加纳民众",
    "link": "http://www.news.cn/20261029/42574808837e4d008b58db8376f95a01/c.html",
    "pub_date": "2026-10-29 18:48:28",
    "author": "",
    "description": "新华社阿克拉10月29日电 题：“吉祥方舟”情暖加纳民众 新华社记者高剑飞 近一年来，45岁的加纳工程师尤金·阿马蒂·安南一直饱受疝气折磨，病情严重到让他难以正常工作，但治疗费用过于高昂，令人望而却步。 安南的治疗迎来了转机。当地时间23日，中国海军“吉祥方舟”号医院船抵达加纳特马港，进行友好访问并提供医疗服务。这是中国海军医院船首次访问这个西非国家。 “26日早上我母亲陪我过来，当天下午4点30分左右，医疗团队就在手术室里成功为我做了…",
