    "description": "新华社北京10月29日电 国际天文学联合会小行星中心27日宣布，在太阳系外围发现了一个矮行星候选体，如确认将成为太阳系经正式认定的第六颗矮行星。 美国研究人员利用电脑程序分析智利薇拉·鲁宾天文台的观测数据发现了这颗冰质星体，暂时将其命名为2026 ED138。 研究人员估计，2026 ED138距离太阳46个天文单位，即地球与太阳平均距离的46倍，比冥王星到太阳40个天文单位的距离还要远。2026 ED138也因此属于“海王星外天体”，…",
    "content": "新华社北京10月29日电 国际天文学联合会小行星中心27日宣布，在太阳系外围发现了一个矮行星候选体，如确认将成为太阳系经正式认定的第六颗矮行星。 美国研究人员利用电脑程序分析智利薇拉·鲁宾天文台的观测数据发现了这颗冰质星体，暂时将其命名为2026 ED138。 研究人员估计，2026 ED138距离太阳46个天文单位，即地球与太阳平均距离的46倍，比冥王星到太阳40个天文单位的距离还要远。2026 ED138也因此属于“海王星外天体”，即轨道在海王星之外、绕太阳公转的一类小天体。 并非所有“海王星外天体”都是矮行星…"
