    "title": "党旗在基层一线高高飘扬丨山西阳曲县泥屯镇：党建更实了，日子更美了",
    "link": "http://www.news.cn/20261029/28101b584e28429abd30d36a5f184f29/c.html",
    "pub_date": "2026-10-29 18:30:38",
    "author": "",
    "description": "金秋时节，在山西省太原市阳曲县泥屯镇归朝村，几位村民正把本村种植的一批半人高的葫芦打包严实、抬上卡车。村支书郑建国一边认真统计个数，一边指挥装车。装完车，他就要和几位村“两委”干部、种植大户一同赶往山东聊城，参加葫芦文化艺术节。 归朝村所在的泥屯镇是县里行政村最多的乡镇，21个村庄资源禀赋不同，经营主体多、发展差异大，如何更加有效地推动村庄发展、强化基层治理，是镇党委、政府面临的一大难题。2024年，泥屯镇设立山西省首个实体化运行的乡镇…",
