    "pub_date": "2026-10-29 18:11:05",
    "author": "",
    "description": "新华社北京10月29日电（记者任军、吴雨）记者10月29日从中国人民银行获悉，近日中国人民银行与智利中央银行续签双边本币互换协议，互换规模保持500亿元人民币/60000亿智利比索不变，协议有效期五年。 中国人民银行表示，双方再次续签双边本币互换协议，有助于进一步深化两国货币金融合作，促进双边贸易和投资便利化，维护金融市场稳定。",
    "content": "新华社北京10月29日电（记者任军、吴雨）记者10月29日从中国人民银行获悉，近日中国人民银行与智利中央银行续签双边本币互换协议，互换规模保持500亿元人民币/60000亿智利比索不变，协议有效期五年。 中国人民银行表示，双方再次续签双边本币互换协议，有助于进一步深化两国货币金融合作，促进双边贸易和投资便利化，维护金融市场稳定。"
