    "content": "新华社北京10月29日电（记者曹嘉玥、冯歆然）外交部发言人郭嘉昆29日在例行记者会上表示，中方再次敦促美方认真倾听国际社会的正义呼声，立即停止对古巴的封锁制裁，立即停止以武力等任何形式对古巴胁迫施压。 有记者问：当地时间10月28日，第81届联合国大会通过“必须终止美国对古巴的经济、商业和金融封锁”决议。请问中方对此有何评论？ 郭嘉昆说，美国对古巴的非法经济封锁和单边经济制裁已经持续64年，给古巴人民带来深重灾难。自1992年起，联合国大会已连续34次以压倒性多数通过“必须终止美国对古巴的经济、商业和金融封锁”决议…"
