    "content": "近日，网红球迷退钱哥何胜在社交平台发布视频，官宣已正式办理离职手续，告别任职二十余年的设计院，结束长期一边上班、一边追赛做内容的斜杠状态，未来将全职投身自媒体与足球相关领域。 视频里，何胜走进单位大楼，言语间满是不舍。他配文写道，虽然已经很久没有到岗上班，但再度踏入大楼心中感慨万千，往日加班的一幕幕涌上心头，感谢单位多年的关照与培养，祝愿公司发展越来越好。 据介绍，何胜大学毕业后便进入这家设计院，从事结构设计工作，这栋大楼搬迁时的图纸，正是由他亲手绘制。从毕业成家到在岗位上独当一面，这里承载了他二十多年的人生轨迹。…"
