    "author": "",
    "description": "中共五中全会闭幕，官方公报显示，出席的中央委员和候补中央委员人数，比去年四中全会分别减少六人和30人。 中国共产党第二十届中央委员会第五次全体会议，于2026年10月26日至29日在北京举行。出席这次全会的有，中央委员162人，候补中央委员117人。 中国共产党第二十届中央委员会第四次全体会议，于2025年10月20日至23日在北京举行。出席这次全会的有，中央委员168人，候补中央委员147人。",
