    "description": "新华社哈尔滨10月29日电（记者黄腾）记者从黑龙江省气象台了解到，10月29日夜间起，黑龙江省气温将自西向东逐步下降，未来48小时大兴安岭、黑河、伊春等地最低气温将下降8至10摄氏度，局地可达12摄氏度，其他大部地区下降6至8摄氏度。大兴安岭、黑河北部有中到大雪，大兴安岭北部局地有大到暴雪，新增积雪深度5至10厘米，其他大部分地区有阵雪或雨夹雪。 受降雪和降温影响，预计大兴安岭、黑河北部、伊春北部等地将出现对交通有影响的道路积雪或结冰，…",
    "content": "新华社哈尔滨10月29日电（记者黄腾）记者从黑龙江省气象台了解到，10月29日夜间起，黑龙江省气温将自西向东逐步下降，未来48小时大兴安岭、黑河、伊春等地最低气温将下降8至10摄氏度，局地可达12摄氏度，其他大部地区下降6至8摄氏度。大兴安岭、黑河北部有中到大雪，大兴安岭北部局地有大到暴雪，新增积雪深度5至10厘米，其他大部分地区有阵雪或雨夹雪。 受降雪和降温影响，预计大兴安岭、黑河北部、伊春北部等地将出现对交通有影响的道路积雪或结冰，部分时段能见度较低，道路交通气象风险等级较高。10月30日至31日黑龙江省大部地…"
