    "description": "六十多年前，三千多名南方孤儿嗷嗷待哺。关键时刻，内蒙古大草原张开怀抱，哺育了这些“国家的孩子”，成就了“三千孤儿入内蒙”这段佳话。 原本远隔千里，如今生死相依。没有血缘联系，又早已骨肉相连。当年的南方娃娃，现在儿孙满堂。他们在草原上长大成人，建功立业。在他们眼中，内蒙古大草原就是此生难离的故土。 近日，新华社记者走近“国家的孩子”，重温那段感人至深的岁月，感受他们美好幸福的晚年生活。 丹迪嘎肖像照（10月28日摄）。新华社记者 刘金海 …",
