    "content": "今年前九个月，德国大众汽车在中国的合资企业录得1.13亿欧元（1.61亿新元）的营业亏损，同比由盈转亏，公司首席财务官安特利茨（Arno Antlitz）敦促加快削减成本。 据彭博社报道，大众汽车星期四（10月29日）发布第三季度财报。去年首九个月，按权益法核算的中国合资企业则盈利7亿4400万欧元。 同期营收由盈转亏显示，大众汽车最重要的利润来源之一，如今已成为业绩的主要拖累，本土竞争对手则持续抢占市场份额。 公司CFO安特利茨说，前九个月的业绩显示，“我们不能再浪费时间，必须迅速果断地采取行动。”大众股价星期四…"
