    "author": "",
    "description": "新华社广州10月29日电（记者王雨萧）作为商务部2026年“中华美食文化季”促消费重点活动，由中国饭店协会主办的第二十七届中国美食节29日在广东佛山南海开幕。本届中国美食节将聚焦餐饮消费新业态、新场景、新模式，通过“会+展+赛+集”形式助力培育地域餐饮品牌，激活餐饮业创新动能，释放餐饮消费活力。 餐饮业是促消费、惠民生、稳就业的重要领域，国务院印发的《关于推进服务业扩能提质的意见》明确提出“培育健康安全、营养均衡、体现地方特色的餐饮服务…",
    "content": "新华社广州10月29日电（记者王雨萧）作为商务部2026年“中华美食文化季”促消费重点活动，由中国饭店协会主办的第二十七届中国美食节29日在广东佛山南海开幕。本届中国美食节将聚焦餐饮消费新业态、新场景、新模式，通过“会+展+赛+集”形式助力培育地域餐饮品牌，激活餐饮业创新动能，释放餐饮消费活力。 餐饮业是促消费、惠民生、稳就业的重要领域，国务院印发的《关于推进服务业扩能提质的意见》明确提出“培育健康安全、营养均衡、体现地方特色的餐饮服务”。 记者了解到，本届美食节设置美食产业发展大会、7场平行会议以及饭店业文创大赛…"
