    "content": "新华社合肥10月29日电（记者水金辰）秋风掠过田畴，大地铺展开层层叠叠的金黄。秋天的乡村，正是“三秋”大忙时：一边抢收，一边整地播种，一边张罗着粮食归仓。秋收收什么？秋种种什么？收的粮食去哪儿了？记者采访了相关专家，并在一线做了探访。 秋收：天南地北，收的不一样 中国科学院院士钱前说，我国幅员辽阔，南北气候、积温条件差别很大，夏种秋收的作物各不相同。 在东北黑土地上，玉米、水稻、大豆是主角。黑土地无霜期短，秋收必须抢抓霜冻到来前的窗口期。在黄淮海平原，玉米、花生、大豆等旱粮作物已经基本收获归仓。在长江流域，农民不久…"
